contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address target) public payable {
        require(target != address(0) && target != address(c), "invalid target");
        uint256 beforeBal = address(c).balance;
        uint256 targetBefore = target.balance;

        bool reverted;
        c.migrateTo(target); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterBal = address(c).balance;
        uint256 targetAfter = target.balance;

        assert(
            (reverted && afterBal == beforeBal) ||
            (!reverted && afterBal == 0 && targetAfter == targetBefore + beforeBal)
        );
    }

    receive() external payable {}
}

