// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(address target) internal {
        vm.assume(target != address(0) && target != address(c));
        uint256 beforeBal = address(c).balance;
        uint256 targetBefore = target.balance;
        bool reverted;
        try c.migrateTo(target) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterBal = address(c).balance;
        uint256 targetAfter = target.balance;
        assertTrue((reverted && afterBal == beforeBal) ||
            (!reverted && afterBal == 0 && targetAfter == targetBefore + beforeBal));
    }

    function testFuzz_run(address target) public {
        vm.assume(target.code.length == 0 && uint160(target) > 0xffff && target != address(this) && target != address(c) && target != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && target != 0x000000000000000000636F6e736F6c652e6c6f67 && target != 0x4e59b44847b379578588920cA78FbF26c0B4956C && target != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(target);
    }

    receive() external payable {}
}
